  if (marker.preferredLetter && !/^[D-Z]$/.test(marker.preferredLetter)) throw new Error("稳定盘符设置无效")
  const candidates = marker.preferredLetter ? [marker.preferredLetter] : ["X", "Y", "Z", "R", "Q", "P", "N", "M"]
