  }

  remove(id: string): void {
    this.db.transaction(() => {
      if (!this.document(id)) return
      this.clearChunks(id)
      this.db.query("DELETE FROM knowledge_documents WHERE id=?").run(id)
      this.changed()
    })()
  }
